package dev.taihei.mihon

import zio.test.*

import dev.taihei.mihon.sources.ResourceLoader

// The JVM reads the data files from the classpath, Scala.js from the copy the build compiles in.
// Both must give exactly the files in shared/resources: DataManifest, generated by the build from
// the files on disk, holds each file's length and String.hashCode (specified, so the same on both
// platforms), and every file must load with those.
object DataSpec extends ZIOSpecDefault:

  def spec = suite("DataSpec")(
    test("every data file loads as the file on disk holds it") {
      val files = DataManifest.files.toSeq.sortBy(_._1)
      assertTrue(
        files.size > 2,
        files.forall((path, fingerprint) =>
          val text = ResourceLoader.load(path)
          (text.length, text.hashCode) == fingerprint
        ),
      )
    },
    test("every language has its four files, and there are no others") {
      val expected = Mihon.languages.flatMap { l =>
        val dir     = s"/dev/taihei/mihon/data/${l.tag}"
        val country = Mihon.seeded(1L, l).address.countryCode
        Seq(s"$dir/text.json", s"$dir/names.json", s"$dir/countries.json", s"$dir/country-$country.json")
      }.toSet + "/dev/taihei/mihon/data/languages.json"
      assertTrue(DataManifest.files.keySet == expected)
    },
    test("an unknown file is a packaging error, not empty data") {
      assertTrue(scala.util.Try(ResourceLoader.load("/dev/taihei/mihon/data/no-such.json")).isFailure)
    },
  )

end DataSpec
